def sign(n):
    if n > 0:
        return "positive"
    elif n < 0:
        return "negative"
    return "zero"

def sum_to(n):
    s = 0
    for i in range(1, n + 1):
        s = s + i
    return s

def count_down(n):
    steps = 0
    while n > 0:
        n = n - 1
        steps = steps + 1
    return steps

def count_big(xs):
    count = 0
    for x in xs:
        if x > 10:
            count = count + 1
    return count

def smallest(xs):
    best = xs[0]
    for x in xs:
        if x < best:
            best = x
    return best

def index_of(xs, wanted):
    for i in range(len(xs)):
        if xs[i] == wanted:
            return i
    return -1

def count_even(n):
    count = 0
    for i in range(1, n + 1):
        if i % 2 == 0:
            count = count + 1
    return count

def contains(xs, x):
    for y in xs:
        if y == x:
            return True
    return False

def max_of(xs):
    best = xs[0]
    for x in xs:
        if x > best:
            best = x
    return best

def fizz(n):
    if n % 3 == 0:
        return "Fizz"
    return str(n)
